using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "DuneSurfingAction", menuName = "Data/Battle/Battle Actions/Sothis/DuneSurfing Action")]
public class DuneSurfingAction : MultipleSoulHeatTierAction
{
	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		if (GetSoulHeatAmountToUse(activateFeedback: false) >= secondActionSoulHeatAmountToUse)
		{
			return thirdBattleAction.CheckConditionToBeCasted(playerHand, diceOwnerEnum);
		}
		return true;
	}
}
